#include "wsoundthermal89.h"
static wsound89_i16 sat(wsound89_i32 v){if(v>32767)return 32767;if(v<-32768)return -32768;return(wsound89_i16)v;}static wsound89_i16 nz(wsoundthermal89_context*c){c->state=c->state*1664525U+1013904223U;return(wsound89_i16)((c->state>>16)&65535U);}
wsound89_result wsoundthermal89_init(wsoundthermal89_context*c,wsound89_u32 seed){if(!c)return WSOUND89_EINVAL;c->state=seed?seed:0x54484552U;c->accum=0;c->heat_q15=c->click=c->res1=c->res2=0;c->cooling_q15=32740;c->active=0;c->material=WSOUNDTHERMAL89_BARREL;return WSOUND89_OK;}void wsoundthermal89_add_heat(wsoundthermal89_context*c,wsoundthermal89_material m,wsound89_u16 h){if(!c)return;c->material=m;c->heat_q15+=h;if(c->heat_q15>32767)c->heat_q15=32767;c->active=1;}
wsound89_i16 wsoundthermal89_process_sample(wsoundthermal89_context*c){wsound89_i32 n,mix;wsound89_u32 rate;if(!c||!c->active)return 0;rate=10U+((wsound89_u32)c->heat_q15>>5);c->accum+=rate;if(c->accum>65535U){c->accum-=65535U;n=nz(c);c->click=((wsound89_i32)n*(5000+(c->heat_q15>>1)))>>15;}else c->click=(c->click*18000)>>15;c->res1+=(c->click-c->res1)>>2;c->res2+=(c->res1-c->res2)>>4;mix=c->click+(c->res1>>1);if(c->material==WSOUNDTHERMAL89_SUPPRESSOR)mix+=c->res2;else if(c->material==WSOUNDTHERMAL89_POLYMER)mix=(mix>>1)+(c->res2>>2);c->heat_q15=(c->heat_q15*c->cooling_q15)>>15;if(c->heat_q15<10&&c->click<8&&c->click>-8)c->active=0;return sat(mix);}
